package app.vibefinancier;

import android.app.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.math.*;
import java.time.*;
import java.util.*;

final class CurrencyScreen {
    interface Actions {void refresh();void history();void manual();void repair();void operation(String id);}
    static void create(Activity a,LinearLayout body,List<JSONObject> values,String base,String error,Actions actions)throws Exception {
        body.addView(Ui.text(a,"Reference quotes · "+base,20,Ui.INK));LinearLayout buttons=new LinearLayout(a);buttons.addView(Ui.button(a,"Update rates",actions::refresh),new LinearLayout.LayoutParams(0,-2,1));buttons.addView(Ui.button(a,"Load 7 days",actions::history),new LinearLayout.LayoutParams(0,-2,1));body.addView(buttons);body.addView(Ui.button(a,"Manual rate",actions::manual));body.addView(Ui.button(a,"Review historical crypto rates",actions::repair));
        body.addView(Ui.text(a,"Current valuation and unrealized gain / loss. Tap a deposit to inspect its saved rate.",12,Ui.MUTED));body.addView(Ui.button(a,"How is this calculated?",()->Ui.message(a,"Deposit valuation","FIFO unrealized benchmark for remaining deposits, excluding debt accounts. Internal transfers preserve acquisition cost. Unknown deposit rates make the result partial. Daily reference quotes are not execution prices.")));if(!error.isEmpty())body.addView(Ui.text(a,error,13,0xffe36c6c));
        Set<String> currencies=new TreeSet<>();Map<String,JSONObject> latest=new HashMap<>();for(JSONObject p:values){if(p.optString("entity").equals("account"))currencies.add(p.optString("currency"));if(p.optString("entity").equals("rate")&&p.optString("base").equals(base))latest.put(p.optString("currency"),p);}
        for(String currency:currencies){if(currency.equals(base))continue;JSONObject q=latest.get(currency);CurrencyPosition position=new CurrencyPosition(values,currency,base);LinearLayout card=Ui.card(a,body);card.addView(Ui.text(a,currency,23,Ui.INK));card.addView(Ui.text(a,"Balance: "+Dashboard.format(position.balance,currency),17,Ui.INK));
            if(q==null)card.addView(Ui.text(a,"No quote · update rates or enter a manual rate",13,Ui.MUTED));else{BigDecimal rate=Money.decimal(q.getString("rate"));card.addView(Ui.text(a,"1 "+currency+" = "+Dashboard.format(rate,base),18,Ui.INK));card.addView(Ui.text(a,q.optString("source")+" · "+q.optString("asof")+"\nFetched: "+q.optString("fetched_at",q.optString("asof"))+(q.optBoolean("manual")?" · manual lock":""),11,Ui.MUTED));BigDecimal profit=position.profit(rate);card.addView(Ui.text(a,"Current value: "+display(position.balance.multiply(rate),base)+"\nKnown remaining cost: "+display(position.cost,base)+"\nUnrealized gain / loss: "+display(profit,base)+(position.partial?" · partial":""),16,profit.signum()<0?0xffe36c6c:Ui.GREEN));if(position.partial)card.addView(Ui.text(a,"Known units: "+Dashboard.format(position.knownUnits,currency)+". Unpriced units and negative positions are excluded from gain / loss.",12,Ui.MUTED));}
            List<JSONObject> points=new ArrayList<>();for(JSONObject p:values)if(Set.of("quote","rate").contains(p.optString("entity"))&&p.optString("currency").equals(currency)&&p.optString("base").equals(base))points.add(p);points.sort(Comparator.comparing(p->p.optString("asof")));if(points.size()>90)points=new ArrayList<>(points.subList(points.size()-90,points.size()));
            if(points.size()>1){card.addView(new Chart(a,points,position.deposits),new LinearLayout.LayoutParams(-1,Ui.dp(a,145)));card.addView(Ui.text(a,points.get(0).optString("asof")+" — "+points.get(points.size()-1).optString("asof")+"\n● Deposit markers · tap a deposit below for its operation",11,Ui.MUTED));}else card.addView(Ui.text(a,"More quote observations are needed for a chart.",12,Ui.MUTED));
            for(int i=Math.max(0,position.deposits.size()-20);i<position.deposits.size();i++){CurrencyPosition.Deposit deposit=position.deposits.get(i);TextView entry=Ui.text(a,"● "+deposit.time+" · +"+Dashboard.format(deposit.units,currency)+"\n"+(deposit.rate==null?"Unknown acquisition rate":"Deposit rate: "+Dashboard.format(deposit.rate,base)),13,Ui.INK);entry.setOnClickListener(v->actions.operation(deposit.id));card.addView(entry);}
            if(!points.isEmpty()){List<JSONObject> observations=points;card.addView(Ui.button(a,"Quote observations",()->{StringBuilder b=new StringBuilder();for(JSONObject p:observations)b.append(p.optString("asof")).append(" · ").append(p.optString("rate")).append(" · ").append(p.optString("source")).append('\n');Ui.message(a,"Quote observations",b.toString());}));}
        }
    }
    private static String display(BigDecimal value,String base){return Dashboard.format(value.setScale(Money.scale(base),RoundingMode.HALF_EVEN),base);}
    private static final class Chart extends View {
        final List<JSONObject> points;final List<CurrencyPosition.Deposit> deposits;final Paint paint=new Paint(3);
        Chart(Activity a,List<JSONObject> points,List<CurrencyPosition.Deposit> deposits){super(a);this.points=points;this.deposits=deposits;setContentDescription("Rate history with deposit markers");}
        private long time(String value){try{return Instant.parse(value).toEpochMilli();}catch(Exception ignored){}try{return LocalDateTime.parse(value).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();}catch(Exception ignored){}try{return LocalDate.parse(value.substring(0,10)).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();}catch(Exception e){return 0;}}
        @Override protected void onDraw(Canvas c){super.onDraw(c);double min=Double.MAX_VALUE,max=-Double.MAX_VALUE;long first=time(points.get(0).optString("asof")),last=time(points.get(points.size()-1).optString("asof"));for(JSONObject p:points){double v=Double.parseDouble(p.optString("rate"));min=Math.min(min,v);max=Math.max(max,v);}float pad=16*getResources().getDisplayMetrics().density,w=getWidth()-2*pad,h=getHeight()-2*pad;Path path=new Path();paint.setColor(Ui.GREEN);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2*getResources().getDisplayMetrics().density);int n=0;for(JSONObject p:points){float x=pad+w*(time(p.optString("asof"))-first)/Math.max(1,last-first),y=pad+h-(float)((Double.parseDouble(p.optString("rate"))-min)/Math.max(1e-18,max-min))*h;if(n++==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xffffc947);for(CurrencyPosition.Deposit d:deposits){long day=time(d.time);if(day<first||day>last)continue;float x=pad+w*(day-first)/Math.max(1,last-first);float y=d.rate==null?getHeight()-pad:pad+h-(float)Math.max(0,Math.min(1,(d.rate.doubleValue()-min)/Math.max(1e-18,max-min)))*h;c.drawCircle(x,y,4*getResources().getDisplayMetrics().density,paint);}}
    }
}
